import albumsData from '../../../catalog/albums.json'
import speciesData from '../../../catalog/species.json'

/** A colour album as generated by catalog/scripts/build_catalog.py (catalog/albums.json). */
export interface Album {
  id: string
  name: string
  description: string
  order: number
  /** Catalogue colour words gathered in this album. */
  colors: string[]
  speciesCount: number
  /** Every album has exactly one legendary species, found only in that album. */
  legendarySpeciesId: string
}

export type Rarity = 'common' | 'uncommon' | 'legendary'

/** A species' place in one album: a white-and-pink flower is in both albums, with two numbers. */
export interface Membership {
  albumId: string
  number: number
}

/**
 * A species as generated in catalog/species.json (schema: catalog/schema/species.schema.json).
 * Only the fields the app reads are typed here.
 */
export interface Species {
  id: string
  /** The first colour album (its main colour) and the card number there: albums[0]. */
  albumId: string
  number: number
  albums: Membership[]
  scientificName: string
  taxonLevel: 'species' | 'genus' | 'group'
  commonNameIt: string
  family: string
  rarity: Rarity
  dominantColors: string[]
  phenology: 'flowering' | 'fruiting'
  bloomMonths: number[]
  habitat: string
  altitude: string
  regions: string
  sizeNote: string
  description: string
  funFact: string
  cultivated: boolean
  /** true: legally protected; null: possibly protected in some regions (to verify). */
  protected: boolean | null
  protectionNote: string
  toxic: boolean
  toxicNote: string
  /** Catalogue ids of species that look alike. */
  lookalikes: string[]
  textStatus: string
}

export const albums: readonly Album[] = [...(albumsData as Album[])].sort((a, b) => a.order - b.order)

export const species: readonly Species[] = speciesData as Species[]

const albumIndex = new Map(albums.map((album) => [album.id, album]))
const speciesIndex = new Map(species.map((entry) => [entry.id, entry]))

export function albumById(id: string | null | undefined): Album | undefined {
  return id ? albumIndex.get(id) : undefined
}

export function speciesById(id: string): Species | undefined {
  return speciesIndex.get(id)
}

export function inAlbum(entry: Pick<Species, 'albums'>, albumId: string): Membership | undefined {
  return entry.albums.find((membership) => membership.albumId === albumId)
}

/** Different species to collect: one card fills a species in every album it belongs to. */
export const totalSpecies = species.length
